"""f_train.py — TARGET F: train a STUDENT on data generated by our own teacher, then evaluate it
on the REAL validation set (never on generated data, which would be circular).

Usage (env-driven, same conventions as the other runs):
    F_KIND=normal|readable  F_RULE=all|conf50  F_SEED=0  F_LR=1.0  F_LC=0.1
"""
import json
import os
import sys
import time

PROJ = "/run/media/yahya/HARD DISK 4/GlassNet"
sys.path.insert(0, PROJ)
sys.path.insert(0, os.path.join(PROJ, "scripts"))

import numpy as np

KIND = os.environ.get("F_KIND", "normal")
RULE = os.environ.get("F_RULE", "all")
SEED = int(os.environ.get("F_SEED", "0"))
LR = float(os.environ.get("F_LR", "1.0"))
LC = float(os.environ.get("F_LC", "0.1"))
EPOCHS = int(os.environ.get("F_EPOCHS", "40"))
PATIENCE = int(os.environ.get("F_PATIENCE", "10"))
BATCH = int(os.environ.get("F_BATCH", "128"))
TAG = os.environ.get("F_TAG", "f")
# Which epoch's weights to keep.
#   best_lm (default, and what the first F run used): the snapshot at the best LM perplexity.
#       On generated data the LM loss is best at epoch 1-2 and never improves, so this rule
#       SAVES AN UNTRAINED MODEL -- its concepts are audited before they have trained. That
#       defect produced the withdrawn "all nine concepts died" claim.
#   last: the final epoch, so an audit measures the model that was actually trained.
CKPT_RULE = os.environ.get("F_CKPT_RULE", "best_lm")

os.environ.setdefault("T2_CONCEPT_SET", "meaningful_ext")
os.environ.setdefault("T2_N_TAUGHT", "9")
os.environ.setdefault("T2_LAM_A", "0.2")
os.environ.setdefault("T2_LAM_W", "1.0")
os.environ["T2_LAM_CONCEPT"] = str(LC if KIND == "readable" else 0.0)

from glassnet.tensor import set_backend
from glassnet import tiny_data
from glassnet.optim import SGD
import run_t2_iter003 as M

R = os.path.join(PROJ, "runs", "t3")
set_backend("cupy")

DATA = tiny_data.build(win=8, vocab_cap=1500)
Xva = np.asarray(DATA["Xva"])
Yva = np.asarray(DATA["yva"])
V = DATA["V"]

corpus = np.load(os.path.join(R, f"f_corpus_{RULE}.npz"))
Xtr, Ytr = corpus["X"], corpus["y"]
if os.environ.get("F_REAL_DATA", "0") == "1":
    # CONTROL: the identical script, identical hyperparameters, trained on REAL data instead of
    # generated data. If this does not reproduce the teacher's ~81 ppl, the script is broken and
    # any conclusion about the generated corpus is worthless.
    Xtr = np.asarray(DATA["Xtr"])
    Ytr = np.asarray(DATA["ytr"])
    print("*** CONTROL RUN: training on REAL data, not generated ***")
print(f"student {KIND} | rule {RULE} | seed {SEED} | lr {LR} lc {LC}")
print(f"training windows: {len(Xtr)} (generated) | validation: {len(Xva)} (REAL)")


def _host(a):
    """cupy forbids implicit host conversion (the project's own convention: use .get())."""
    return a.get() if hasattr(a, "get") else np.asarray(a)


def evaluate(net):
    out = net.forward(Xva)
    logits = _host(out["logits"].data)
    pred = logits.argmax(1)
    acc = float((pred == Yva).mean())
    z = logits - logits.max(1, keepdims=True)
    p = np.exp(z)
    p /= p.sum(1, keepdims=True)
    ppl = float(np.exp(-np.log(np.maximum(p[np.arange(len(Yva)), Yva], 1e-12)).mean()))
    return acc, ppl


rng = np.random.default_rng(SEED)
net = M.TinyLM3(V, 9, 64, 8, rng=rng, lam_concept=(LC if KIND == "readable" else 0.0))
opt = SGD(net.parameters(), LR)
best = {"acc": -1.0, "ppl": float("inf"), "epoch": -1, "state": None}
bad = 0
t0 = time.time()
for ep in range(1, EPOCHS + 1):
    idx = rng.permutation(len(Xtr))
    for s in range(0, len(Xtr), BATCH):
        b = idx[s:s + BATCH]
        opt.zero_grad()
        loss, _ = net.loss(Xtr[b], Ytr[b])
        loss.backward()
        opt.step()
    acc, ppl = evaluate(net)
    snap = {k: _host(v.data) for k, v in
            (("emb", net.emb), ("Wc", net.concept.W), ("bc", net.concept.b),
             ("Wa", net.answer.W), ("ba", net.answer.b))}
    last_snap = snap
    if CKPT_RULE == "last":
        # keep the most recent epoch -- on generated data the LM loss never improves, so a
        # best-LM rule would save epoch 1 and audit an untrained concept layer
        best = {"acc": acc, "ppl": ppl, "epoch": ep, "state": snap}
    elif ppl < best["ppl"] - 1e-6:
        best = {"acc": acc, "ppl": ppl, "epoch": ep, "state": snap}
        bad = 0
    else:
        bad += 1
    if ep % 5 == 0 or ep == 1:
        print(f"  ep {ep:>3} val acc {acc*100:6.2f}%  ppl {ppl:8.4f}  "
              f"(best {best['ppl']:.4f} @ {best['epoch']}, bad {bad}, {time.time()-t0:.0f}s)")
    if bad >= PATIENCE and ep >= 10:
        print(f"  early stop at epoch {ep}")
        break

res = {"model": KIND, "rule": RULE, "seed": SEED, "lr": LR, "lam_concept": LC,
       "val": best["acc"] * 100.0, "val_ppl": best["ppl"], "best_epoch": best["epoch"],
       "stopped_at": ep, "n_train_windows": int(len(Xtr)), "secs": time.time() - t0,
       "params": int(sum(p.data.size for p in net.parameters())),
       "train_source": "generated"}
os.makedirs(os.path.join(R, "ckpt"), exist_ok=True)
np.savez(os.path.join(R, "ckpt", f"student_{KIND}_{RULE}_{TAG}_seed{SEED}.npz"), **best["state"])
f = os.path.join(R, f"models_f_{TAG}_{KIND}_{RULE}.json")
old = json.load(open(f)) if os.path.exists(f) else []
old = [x for x in old if x["seed"] != SEED] + [res]
json.dump(old, open(f, "w"), indent=1)
print(f"\nSTUDENT {KIND}/{RULE}/seed{SEED}: val acc {res['val']:.2f}%  ppl {res['val_ppl']:.4f} "
      f"(best epoch {res['best_epoch']})")
print(f"saved {f}")
